import{f as s,o as e,c as i,a6 as a}from"./chunks/framework.Dd1qhYRL.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),n={name:"getting-started/installation.md"};function l(d,t,h,o,r,p){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>Install the noorm CLI, then the SDK and the agent skill if you need them.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://noorm.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Installing noorm v1.5.1 (darwin-arm64) to /Users/ada/.local/bin...</span></span>
<span class="line"><span>Installed noorm v1.5.1 to /Users/ada/.local/bin/noorm</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1.5.1</span></span></code></pre></div><p>The binary needs no runtime and includes the database drivers for PostgreSQL, MySQL, SQLite, and SQL Server. For npm, Windows, and the GitHub mirror, see <a href="/download.html">Download</a>.</p><p><code>noorm</code> on its own prints the command list. <code>noorm ui</code> opens the <a href="/tui.html">terminal UI</a>.</p><h2 id="install-the-sdk-optional" tabindex="-1">Install the SDK (optional) <a class="header-anchor" href="#install-the-sdk-optional" aria-label="Permalink to “Install the SDK (optional)”">​</a></h2><p>The SDK needs Node 22.13 or newer, <code>kysely</code>, and the driver for your dialect:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @noormdev/sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kysely</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Dialect</th><th>Driver</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>pg</code></td></tr><tr><td>MySQL</td><td><code>mysql2</code></td></tr><tr><td>SQLite</td><td><code>better-sqlite3</code></td></tr><tr><td>SQL Server</td><td><code>tedious</code> and <code>tarn</code></td></tr></tbody></table><p>Drivers are optional peer dependencies, so install only the one you use.</p><h2 id="install-the-agent-skill-optional" tabindex="-1">Install the agent skill (optional) <a class="header-anchor" href="#install-the-agent-skill-optional" aria-label="Permalink to “Install the agent skill (optional)”">​</a></h2><p>The skill tells your coding agent where SQL goes in a noorm project, how SDK calls report errors, and which CLI flags CI needs, so it stops guessing.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> noormdev/noorm/skills</span></span></code></pre></div><p>Without Node.js, GitHub CLI 2.90 or newer installs the same skill:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> noormdev/noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills/noorm</span></span></code></pre></div><h2 id="update-noorm" tabindex="-1">Update noorm <a class="header-anchor" href="#update-noorm" aria-label="Permalink to “Update noorm”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>After a successful update, noorm offers the skill, using the same commands:</p><table tabindex="0"><thead><tr><th>Where <code>noorm update</code> runs</th><th>Skill step</th></tr></thead><tbody><tr><td>A terminal, with <code>npx</code> or <code>gh</code> on <code>PATH</code></td><td>Asks before it installs or updates the skill</td></tr><tr><td>Piped output, with <code>npx</code> or <code>gh</code> on <code>PATH</code></td><td>Prints the command to run</td></tr><tr><td>Neither <code>npx</code> nor <code>gh</code> on <code>PATH</code></td><td>Prints both commands and where to get Node.js and the GitHub CLI</td></tr><tr><td><code>--json</code></td><td>Skips the offer</td></tr></tbody></table><p>A declined or failed skill install does not change the exit code. From the TUI, press <code>u</code> on the home screen.</p><h2 id="how-is-the-download-verified" tabindex="-1">How is the download verified? <a class="header-anchor" href="#how-is-the-download-verified" aria-label="Permalink to “How is the download verified?”">​</a></h2><p>The npm package, <code>noorm update</code>, and the script at <code>raw.githubusercontent.com/noormdev/noorm/master/install.sh</code> compare the binary&#39;s SHA-256 with the <code>checksums.txt</code> published beside it. A mismatch always aborts. The short script at <code>noorm.dev/install.sh</code> does not check yet; install with the GitHub URL when you want the check.</p><p>If <code>checksums.txt</code> cannot be fetched, they stop. <code>NOORM_INSECURE=1</code> overrides that case only:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/noormdev/noorm/master/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NOORM_INSECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --insecure</span></span></code></pre></div><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>noorm: command not found</code></td><td>The install directory is not on <code>PATH</code></td><td>Add the <code>export PATH=&quot;&lt;dir&gt;:$PATH&quot;</code> line the installer prints to your shell profile</td></tr><tr><td><code>NOORM_INSTALL_DIR</code> has no effect</td><td>The variable was set before <code>curl</code>, so only <code>curl</code> sees it</td><td>Set it after the pipe: <code>curl … | NOORM_INSTALL_DIR=~/bin sh</code></td></tr><tr><td>Install stops with &quot;could not verify checksum&quot;</td><td><code>checksums.txt</code> is unreachable or has no entry for your platform</td><td>Retry, or set <code>NOORM_INSECURE=1</code> as shown above</td></tr><tr><td>The SDK cannot connect and reports a missing driver</td><td>The driver is a peer dependency</td><td>Install the driver for your dialect</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/getting-started/first-build.html">First build</a>: <code>noorm init</code>, a config, and a built schema</li><li><a href="/getting-started/concepts.html">Concepts</a>: the two folders and how databases reach the same schema</li><li><a href="/download.html">Download</a>: every install method and option</li></ul>`,31)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
